  /* ---------- Allocator: always show the authoritative next OFFLINE turn ---------- */
  function isOnline(q){var m=String(q&&q.attendanceMode||'').toUpperCase();return m==='ONLINE'||m==='REMOTE'||m==='DIGITAL'}
  function nextOffline(){var q=(app.fx.queue&&app.fx.queue.waiting)||[];return q.filter(function(x){return !isOnline(x)&&['WAITING','CALLED','CALL_GRACE'].includes(x.state)}).slice().sort(function(a,b){var at=String(a.registeredAt||''),bt=String(b.registeredAt||'');return at.localeCompare(bt)||Number(a.token)-Number(b.token)})[0]||null}
  function stationForSession(){var s=app.fx.final6&&app.fx.final6.allocatorSession;if(!s)return null;return (app.fx.queue.stations||[]).find(function(x){return x.id===s.station})||null}
  window.p64TakeNextOfflineBuyer=function(){var q=nextOffline();if(!q){T('No offline buyer is waiting right now');return}try{if(q.state==='WAITING'&&typeof f6AllocatorCall==='function'){f6AllocatorCall(q.token);return}if(typeof p59StartAllocation==='function'){q.state='CALL_GRACE';p59StartAllocation(q.token);return}}catch(_){ }
    var st=(app.fx.queue.stations||[]).find(function(x){return x.state==='FREE'||!x.token});if(!st){T('No free Allocator seat');return}Object.assign(st,{token:q.token,buyer:q.buyer,eoi:q.eoi,eligible:(q.eligible||[]).slice(),preferred:(q.preferred||[]).slice(),attendanceMode:q.attendanceMode,state:'SELECTION_ACTIVE',unit:null,tx:null});q.state='CALLED';app.fx.final6.allocatorSession={station:st.id,token:q.token,buyer:q.buyer,customerId:q.customerId||null,attendanceMode:q.attendanceMode};A('ALLOCATOR_ASSIGNED','#'+q.token,q.buyer+' → '+st.id,'ALLOCATOR');R()};
  function allocatorHTML(){var st=stationForSession(),q=nextOffline();var current=st?'<div class="p64-nextbuyer"><div class="token">#'+E(st.token)+'</div><div class="name">'+E(st.buyer)+'</div><div class="meta"><span>'+E(st.id)+'</span><span>'+E(st.attendanceMode||'SALES CENTER')+'</span><span>Eligible: '+E((st.eligible||[]).join(', ')||'—')+'</span></div><div class="p64-actions"><button class="p64-btn primary" onclick="go(\''+(P['a-site']?'a-site':'b-site')+'\')">Continue with this buyer → Master Plan</button><button class="p64-btn" onclick="go(\'a-handoff\')">Lock & Handoff</button></div></div>':q?'<div class="p64-nextbuyer"><small style="font-size:6.5px;font-weight:900;color:#5d7390">NEXT OFFLINE TURN • ASSIGNED BY SHARED QUEUE</small><div class="token">#'+E(q.token)+'</div><div class="name">'+E(q.buyer)+'</div><div class="meta"><span>'+E(q.attendanceMode||'SALES CENTER')+'</span><span>'+E(q.eoi||'EOI')+'</span><span>'+E(q.state)+'</span></div><div class="p64-actions"><button class="p64-btn primary" onclick="p64TakeNextOfflineBuyer()">Start assisted allocation with this buyer</button></div></div>':'<div class="p64-card"><h4>No offline buyer waiting</h4><p>The shared queue has no Sales Center buyer ready for an Allocator seat.</p></div>';
    return '<div class="p64-shell"><div class="p64-hero"><div><small>ALLOCATOR • SHARED QUEUE TRUTH</small><h3>The buyer is chosen by the queue, not by the Allocator.</h3><p>PRENEURA always exposes the next eligible OFFLINE / Sales Center turn. Continue with that buyer through Master Plan → Building → Floor → Exact Unit → Lock & Handoff.</p></div>'+pill(st?'IN SESSION':q?'READY NOW':'WAITING',st?'ok':q?'info':'warn')+'</div>'+current+'</div>'}
  var baseAllocator=P['a-desk']&&P['a-desk'].render; if(baseAllocator){P['a-desk'].render=function(){return allocatorHTML()+'<div style="margin-top:10px">'+baseAllocator()+'</div>'}};

  /* ---------- Transaction Operator: exact contract print + signed/fingerprinted upload ---------- */
  function exactContractSummary(){var c=app.fx.contract||{},t=app.fx.transaction||{},u=unitById(t.unit);return {id:c.id||'NOT GENERATED',hash:c.hash||'',buyer:t.buyer||'—',unit:t.unit||'—',price:u&&u.price||0,tx:t.id||'—',payment:t.payment&&t.payment.reference||'—'}}
  window.p64PrintExactContract=function(){if(!app.fx.contract.generated){p64GenerateExactContract();if(!app.fx.contract.generated)return}var s=exactContractSummary(),w=window.open('','_blank','width=920,height=760');if(!w){T('Allow pop-ups to print the exact contract');return}w.document.write('<!doctype html><html><head><title>'+E(s.id)+'</title><style>body{font-family:Arial;padding:36px;color:#17202d}h1{font-size:24px}table{width:100%;border-collapse:collapse;margin:20px 0}td,th{border:1px solid #cfd7e0;padding:10px;text-align:left}.sign{display:grid;grid-template-columns:1fr 1fr;gap:50px;margin-top:70px}.line{border-top:1px solid #17202d;padding-top:8px}small{color:#667386}</style></head><body><small>PRENEURA EXACT CONTRACT • '+E(s.id)+'</small><h1>Property Sale / Reservation Contract</h1><table><tr><th>Buyer</th><td>'+E(s.buyer)+'</td></tr><tr><th>Exact unit</th><td>#'+E(s.unit)+'</td></tr><tr><th>Transaction</th><td>'+E(s.tx)+'</td></tr><tr><th>Price</th><td>'+E(money(s.price))+'</td></tr><tr><th>Payment reference</th><td>'+E(s.payment)+'</td></tr><tr><th>Document hash</th><td>'+E(s.hash)+'</td></tr></table><p>This print represents the exact immutable PRENEURA transaction snapshot. Verify identity, signatures and fingerprint/biometric receipt before uploading the executed copy.</p><div class="sign"><div class="line">Buyer signature / fingerprint</div><div class="line">Authorized company signature</div></div><script>window.onload=function(){window.print()}<\/script></body></html>');w.document.close();A('CONTRACT_PRINTED',s.id,s.buyer+' • unit #'+s.unit,'TRANSACTION_OPERATOR')};
  window.p64UploadExecutedContract=function(){var file=document.getElementById('p64ExecutedFile')?.files?.[0],bio=(document.getElementById('p64ExecutedBio')?.value||'').trim();if(!file||!bio){T('Upload the signed contract and enter the fingerprint/biometric verification reference');return}X.executedContract={file:file.name,size:file.size,biometricReceipt:bio,uploadedAt:new Date().toISOString(),uploadedBy:'TRANSACTION_OPERATOR',verified:false};A('EXECUTED_CONTRACT_UPLOADED',app.fx.contract.id,file.name+' • '+bio,'TRANSACTION_OPERATOR');T('Executed contract uploaded for verification');R()};
  window.p64VerifyExecutedContract=function(){if(!X.executedContract){T('Upload the signed/fingerprinted contract first');return}X.executedContract.verified=true;X.executedContract.verifiedAt=new Date().toISOString();var c=app.fx.contract;c.generated=true;c.status='SIGNED';c.signedAt=c.signedAt||new Date().toISOString();c.evidence=c.evidence||[];c.evidence.push({type:'PHYSICAL_SIGNED_CONTRACT_VERIFIED',at:X.executedContract.verifiedAt,file:X.executedContract.file,receipt:X.executedContract.biometricReceipt,actor:'TRANSACTION_OPERATOR'});app.fx.transaction.state='CONTRACT_SIGNED';A('EXECUTED_CONTRACT_VERIFIED',c.id,X.executedContract.file+' • '+X.executedContract.biometricReceipt,'TRANSACTION_OPERATOR');try{if(typeof f6BuildPropertyFromTransaction==='function')f6BuildPropertyFromTransaction()}catch(_){ }T('Signed exact contract verified and property record updated');R()};
  function contractDesk(){var c=app.fx.contract||{},miss=checks().filter(function(x){return !x.ok}),x=X.executedContract;return '<div class="p64-card"><div class="p64-card-head"><div><h4>Exact Contract Execution Desk</h4><p>Generate the exact transaction contract, print it for offline signature/fingerprint, then upload and verify the executed copy.</p></div>'+pill(c.status||'DRAFT',c.status==='SIGNED'?'ok':c.generated?'info':'warn')+'</div><div class="p64-grid2"><div class="p64-contract-box"><b style="font-size:8.5px">'+E(c.id||'Contract not generated')+'</b><span style="display:block;font-size:6.8px;color:#718094;margin:4px 0">'+E(c.hash||'Exact hash will appear after generation')+'</span><div class="p64-actions"><button class="p64-btn primary" '+(miss.length?'disabled':'')+' onclick="p64GenerateExactContract()">Generate Exact Contract</button><button class="p64-btn dark" '+(!c.generated?'disabled':'')+' onclick="p64PrintExactContract()">Print Exact Contract</button></div>'+(miss.length?'<p style="margin-top:8px;color:#9a5f08">Blocked by: '+E(miss.map(function(m){return m.name}).join(', '))+'</p>':'')+'</div><div class="p64-upload"><label>Upload returned signed + fingerprinted contract</label><input id="p64ExecutedFile" type="file" accept=".pdf,image/*"><input id="p64ExecutedBio" placeholder="Fingerprint / biometric provider receipt" value="'+E(x&&x.biometricReceipt||'')+'" style="margin-top:7px;width:100%;border:1px solid #d9e2ec;border-radius:8px;padding:7px;font-size:7.5px"><div class="p64-actions"><button class="p64-btn primary" onclick="p64UploadExecutedContract()">Upload Executed Contract</button><button class="p64-btn green" '+(!x?'disabled':'')+' onclick="p64VerifyExecutedContract()">Verify & Complete</button></div>'+(x?'<span style="display:block;font-size:6.6px;margin-top:7px">'+E(x.file)+' • '+(x.verified?'VERIFIED':'awaiting verification')+'</span>':'')+'</div></div></div>'}
  var baseReady=P['t-readiness']&&P['t-readiness'].render;if(baseReady){P['t-readiness'].render=function(){return '<div class="p64-shell">'+contractDesk()+'<div>'+baseReady()+'</div></div>'}};
  var baseInbox=P['t-inbox']&&P['t-inbox'].render;if(baseInbox){P['t-inbox'].render=function(){return '<div class="p64-card" style="margin-bottom:10px"><div class="p64-card-head"><div><h4>Contract execution</h4><p>After payment/documents are ready, generate, print and upload the signed/fingerprinted exact contract.</p></div><button class="p64-btn primary" onclick="go(\'t-readiness\')">Open Contract Desk</button></div></div>'+baseInbox()}};

  /* ---------- My Property: paid %, remaining, missed installments and per-row balance ---------- */
  function propertyData(){var ps=app.fx.final6&&app.fx.final6.buyerProperties||[];if(ps.length)return ps[0];if(!X.demoProperty)X.demoProperty={tx:'TX-DEMO-PROPERTY',unit:17,contract:'CTR-DEMO-17',total:4800000,paid:1440000,status:'RESERVED'};return X.demoProperty}
  function installmentData(){var rows=(app.fx.final6&&app.fx.final6.installments||[]).map(function(x){return Object.assign({},x)});if(rows.length)return rows;if(!X.demoInstallments){X.demoInstallments=[{no:'Reservation',due:'2026-06-15',amount:960000,paidAmount:960000,status:'PAID'},{no:'Q1',due:'2026-09-01',amount:240000,paidAmount:120000,status:'MISSED'},{no:'Q2',due:'2026-12-01',amount:240000,paidAmount:0,status:'UPCOMING'},{no:'Q3',due:'2027-03-01',amount:240000,paidAmount:0,status:'SCHEDULED'},{no:'Q4',due:'2027-06-01',amount:240000,paidAmount:0,status:'SCHEDULED'}]}return X.demoInstallments.map(function(x){return Object.assign({},x)})}
  function financeSummary(){var p=propertyData(),rows=installmentData(),now=Date.now();rows.forEach(function(x){x.paidAmount=x.paidAmount!=null?Number(x.paidAmount):(String(x.status).toUpperCase()==='PAID'?Number(x.amount):0);x.remaining=Math.max(0,Number(x.amount||0)-x.paidAmount);var due=Date.parse(x.due);x.overdue=x.remaining>0&&isFinite(due)&&due<now&& !['SCHEDULED','UPCOMING'].includes(String(x.status).toUpperCase())?true:(x.remaining>0&&isFinite(due)&&due<now);x.daysOverdue=x.overdue?Math.max(1,Math.floor((now-due)/86400000)):0});var paid=Number(p.paid||0);var total=Number(p.total||0);if(rows.length)paid=Math.max(paid,rows.reduce(function(a,x){return a+x.paidAmount},0));var remaining=Math.max(0,total-paid),pct=total?Math.round(paid/total*100):0,over=rows.filter(function(x){return x.overdue}),overAmount=over.reduce(function(a,x){return a+x.remaining},0),next=rows.filter(function(x){return x.remaining>0&&!x.overdue}).sort(function(a,b){return Date.parse(a.due)-Date.parse(b.due)})[0];return {p:p,rows:rows,paid:paid,total:total,remaining:remaining,pct:pct,over:over,overAmount:overAmount,next:next}}
  function propertyFinanceHTML(){var f=financeSummary();return '<div class="p64-card"><div class="p64-card-head"><div><h4>Installment & balance summary</h4><p>See exactly what you paid, what is left, and any missed installment before opening the detailed property tabs.</p></div>'+pill(f.over.length?f.over.length+' MISSED':'ON TRACK',f.over.length?'bad':'ok')+'</div><div class="p64-finance-summary"><div class="p64-finance-main"><small>TOTAL CONTRACT</small><strong>'+money(f.total)+'</strong><div class="p64-progress"><i style="width:'+f.pct+'%"></i></div><span>'+f.pct+'% paid • '+(100-f.pct)+'% remaining</span></div><div class="p64-finance-tile"><strong>'+money(f.paid)+'</strong><span>Paid to date</span></div><div class="p64-finance-tile"><strong>'+money(f.remaining)+'</strong><span>Total remaining</span></div><div class="p64-finance-tile '+(f.over.length?'p64-overdue':'')+'"><strong>'+money(f.overAmount)+'</strong><span>'+f.over.length+' missed installment(s)</span></div><div class="p64-finance-tile"><strong>'+(f.next?money(f.next.remaining):'—')+'</strong><span>'+(f.next?'Next due '+E(f.next.due):'No upcoming balance')+'</span></div></div><div class="p64-tablewrap" style="margin-top:10px"><table class="p64-table"><tr><th>Installment</th><th>Due date</th><th>Amount</th><th>Paid</th><th>Left</th><th>Status</th></tr>'+f.rows.map(function(x){return '<tr class="'+(x.overdue?'p64-installment-overdue':x.remaining===0?'p64-installment-paid':'')+'"><td><b>'+E(x.no)+'</b></td><td>'+E(x.due)+(x.overdue?'<small class="p64-delta bad">'+x.daysOverdue+' days overdue</small>':'')+'</td><td>'+money(x.amount)+'</td><td>'+money(x.paidAmount)+'</td><td><b>'+money(x.remaining)+'</b></td><td>'+pill(x.remaining===0?'PAID':x.overdue?'MISSED':String(x.status||'SCHEDULED'),x.remaining===0?'ok':x.overdue?'bad':'warn')+'</td></tr>'}).join('')+'</table></div></div>'}
  var baseProperties=P['b-properties']&&P['b-properties'].render;if(baseProperties){P['b-properties'].render=function(){return '<div class="p64-shell">'+propertyFinanceHTML()+'<div>'+baseProperties()+'</div></div>'}};

  /* ---------- Manager professional overview ---------- */
  function allUnits(){try{return typeof UNITS!=='undefined'?UNITS:[]}catch(_){return []}}
  function statusStats(){var u=allUnits(),s={total:u.length,available:0,hold:0,sold:0,other:0};u.forEach(function(x){var st=String(x.status||'').toLowerCase();if(st==='available')s.available++;else if(['hold','reserved','booked'].includes(st))s.hold++;else if(['sold','completed'].includes(st))s.sold++;else s.other++});return s}
  function buyerRegistry(){return app.fx.rt&&app.fx.rt.registry||[]}
  function brokerCompanies(){return app.fx.final6&&app.fx.final6.brokerCompanies||[]}
  function typeRows(){try{return (UNIT_TYPES||[]).map(function(t){var ids=t.instanceIds||[],us=ids.map(unitById).filter(Boolean),sold=us.filter(function(x){return ['sold','booked','reserved'].includes(String(x.status).toLowerCase())}).length,avail=us.filter(function(x){return String(x.status).toLowerCase()==='available'}).length,min=us.reduce(function(m,x){return !m||x.price<m?x.price:m},0);return {name:t.name,total:us.length,sold:sold,available:avail,min:min,pct:us.length?Math.round(sold/us.length*100):0}})}catch(_){return []}}
  function managerOverview64(){var st=statusStats(),buyers=buyerRegistry(),eligible=buyers.filter(function(b){return b.eoiState==='ELIGIBLE'||b.eoiPaid}).length,queued=(app.fx.queue&&app.fx.queue.waiting||[]).filter(function(q){return ['WAITING','CALL_GRACE','CALLED'].includes(q.state)}).length,props=app.fx.final6&&app.fx.final6.buyerProperties||[],revenue=props.reduce(function(a,p){return a+Number(p.paid||0)},0)+(app.fx.transaction?.payment?.state==='CONFIRMED'?Number(app.fx.transaction.payment.amount||0):0),outstanding=props.reduce(function(a,p){return a+Math.max(0,Number(p.total||0)-Number(p.paid||0))},0),brokers=brokerCompanies(),trs=typeRows(),best=trs.slice().sort(function(a,b){return b.pct-a.pct})[0];return '<div class="p64-shell"><div class="p64-hero"><div><small>EXECUTIVE PROJECT OVERVIEW</small><h3>Everything needed to run the real-estate project from one page.</h3><p>Inventory, sell-through, buyer funnel, collections, brokers, allocation and exceptions are summarized here. Open a workspace only when you need to investigate or act.</p></div><button class="p64-btn primary" onclick="go(\'m-project-data\')">Project Data & Uploads</button></div><div class="p64-kpis"><div class="p64-kpi"><strong>'+st.total+'</strong><span>Total physical units</span></div><div class="p64-kpi good"><strong>'+st.available+'</strong><span>Available now</span></div><div class="p64-kpi"><strong>'+st.sold+'</strong><span>Sold / completed</span></div><div class="p64-kpi warn"><strong>'+queued+'</strong><span>Buyers in shared queue</span></div><div class="p64-kpi"><strong>'+money(revenue)+'</strong><span>Collected / confirmed</span></div><div class="p64-kpi '+(outstanding?'warn':'good')+'"><strong>'+money(outstanding)+'</strong><span>Outstanding contracts</span></div></div><div class="p64-manager-quick"><button class="p64-quick" onclick="go(\'m-phases\')"><b>Projects & Phases</b><span>Choose exact units + prices</span></button><button class="p64-quick" onclick="go(\'m-buyer-control\')"><b>Buyers</b><span>Search any buyer + progress</span></button><button class="p64-quick" onclick="go(\'m-brokers\')"><b>Brokers</b><span>Companies, agents, sales & EOI</span></button><button class="p64-quick" onclick="go(\'m-replay\')"><b>Audit</b><span>Role + user + buyer + step</span></button><button class="p64-quick" onclick="go(\'m-allocation-live\')"><b>Live Allocation</b><span>Queue, seats, locks and channel</span></button></div><div class="p64-grid2"><section class="p64-card"><div class="p64-card-head"><div><h4>Project inventory & sell-through</h4><p>'+st.total+' units • fastest-selling type: '+E(best&&best.name||'—')+'</p></div>'+pill(st.total?Math.round((st.sold+st.hold)/st.total*100)+'% committed':'—','info')+'</div><div class="p64-bar"><i class="available" style="width:'+(st.total?st.available/st.total*100:0)+'%"></i><i class="hold" style="width:'+(st.total?st.hold/st.total*100:0)+'%"></i><i class="sold" style="width:'+(st.total?st.sold/st.total*100:0)+'%"></i></div><div class="p64-tablewrap" style="margin-top:9px"><table class="p64-table"><tr><th>Product</th><th>Total</th><th>Available</th><th>Committed / sold</th><th>Sell-through</th><th>Starting price</th></tr>'+trs.map(function(x){return '<tr><td><b>'+E(x.name)+'</b></td><td>'+x.total+'</td><td>'+x.available+'</td><td>'+x.sold+'</td><td>'+x.pct+'%</td><td>'+money(x.min)+'</td></tr>'}).join('')+'</table></div></section><aside class="p64-card"><h4>Buyer & partner funnel</h4><div class="p64-kpis" style="grid-template-columns:repeat(2,1fr)"><div class="p64-kpi"><strong>'+buyers.length+'</strong><span>Buyer records</span></div><div class="p64-kpi"><strong>'+eligible+'</strong><span>EOI eligible / paid</span></div><div class="p64-kpi"><strong>'+brokers.length+'</strong><span>Broker companies</span></div><div class="p64-kpi"><strong>'+brokers.reduce(function(a,c){return a+(c.agents||[]).length},0)+'</strong><span>Broker agents</span></div></div><div class="p64-actions"><button class="p64-btn primary" onclick="go(\'m-buyer-control\')">Open all buyers</button><button class="p64-btn" onclick="go(\'m-brokers\')">Broker performance</button></div></aside></div><div class="p64-grid2"><section class="p64-card"><h4>Live transaction</h4><div class="p64-tablewrap"><table class="p64-table"><tr><th>Buyer</th><th>Unit</th><th>Payment</th><th>Contract</th><th>State</th></tr><tr><td>'+E(app.fx.transaction?.buyer||'—')+'</td><td>'+E(app.fx.transaction?.unit||'—')+'</td><td>'+pill(app.fx.transaction?.payment?.state||'—',app.fx.transaction?.payment?.state==='CONFIRMED'?'ok':'warn')+'</td><td>'+pill(app.fx.contract?.status||'—',app.fx.contract?.status==='SIGNED'?'ok':'info')+'</td><td>'+E(app.fx.transaction?.state||'—')+'</td></tr></table></div><div class="p64-actions"><button class="p64-btn" onclick="go(\'m-transactions\')">Transactions</button><button class="p64-btn" onclick="go(\'m-replay\')">Audit trail</button></div></section><aside class="p64-card"><h4>Decision signals</h4><p>• '+queued+' buyer(s) currently waiting / called in the shared queue.<br>• '+st.hold+' unit(s) are held/reserved and need conversion or release.<br>• '+money(outstanding)+' remains outstanding on active property records.<br>• '+(best?best.name+' leads current sell-through at '+best.pct+'%.':'No sell-through data yet.')+'</p><div class="p64-actions"><button class="p64-btn primary" onclick="go(\'m-sales-allocation\')">Sales & Allocation</button><button class="p64-btn" onclick="go(\'m-pricing\')">Pricing</button></div></aside></div></div>'}
